def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my_actions = [h[0] for h in history]
    opp_actions = [h[1] for h in history]

    opp_c = sum(1 for a in opp_actions if a == 'C')
    opp_d = n - opp_c
    my_d = sum(1 for a in my_actions if a == 'D')

    if n >= 2 and opp_c == 0:
        return 'D'
    if n >= 5 and opp_d > 0.7 * n:
        return 'D'
    if n >= 5:
        recent = history[-5:]
        recent_opp_d = sum(1 for a, b in recent if b == 'D')
        if recent_opp_d >= 3:
            return 'D'

    if opp_d == 0:
        if my_d == 0:
            if n == 10:
                return 'D'
            return 'C'
        else:
            last_d_idx = -1
            for i in range(n - 1, -1, -1):
                if my_actions[i] == 'D':
                    last_d_idx = i
                    break
            if last_d_idx == n - 1:
                prev_d_idx = -1
                for i in range(last_d_idx - 1, -1, -1):
                    if my_actions[i] == 'D':
                        prev_d_idx = i
                        break
                if prev_d_idx != -1:
                    return 'D'
                else:
                    return 'C'
            else:
                return 'D'

    last_me = my_actions[-1]
    last_opp = opp_actions[-1]

    if last_opp == 'D':
        if n >= 1 and my_actions[-1] == 'D':
            return 'C'
        if n >= 2 and my_actions[-2] == 'D':
            return 'C'
        return 'D'
    else:
        return 'C'
